<template>
  <AuthLayout :loading="processing" :showInfoPanel="false">
    <AuthCard
      :title="$t('forgot_password_header')"
      :success="success_message"
      :error="model['email_error_msg'] || ''"
    >
      <!-- Email input -->
      <q-input
        v-model="model['email']"
        dense
        outlined
        :label="$t('email')"
        class="w-full"
        :error="model['email_error']"
        hide-bottom-space
        data-test="forget-password-email-input"
        @keyup.enter="enterS"
      />

      <!-- Recaptcha -->
      <div v-if="recaptcha_key" class="flex justify-center">
        <vue-recaptcha
          ref="recaptcha"
          :sitekey="recaptcha_key"
          @verify="captcaResp"
        />
      </div>

      <template #actions>
        <q-btn
          unelevated
          color="primary"
          text-color="white"
          :label="$t('resetBtn')"
          class="auth-submit-btn"
          data-test="forget-password-submit-button"
          @click="submitForm()"
          @keyup.enter="enterS"
        />
      </template>
    </AuthCard>

    <template #footer>
      <a
        class="text-sm text-primary cursor-pointer hover:underline"
        @click="user_login()"
        >{{ $t('back_to_login') }}
      </a>
    </template>
  </AuthLayout>
</template>

<script lang="ts">
import axios from 'axios';
import { defineComponent, ref } from 'vue';
import { VueRecaptcha } from 'vue-recaptcha';
import helperUtil from 'src/utils/helperUtil';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import { api, getClientAuthorization } from 'pages/APIs';
import { AuthLayout, AuthCard } from 'src/components/Auth';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  mixins: [helperMixin, helperUtil],
  components: {
    VueRecaptcha,
    AuthLayout,
    AuthCard,
  },
  setup() {
    return {
      model: ref({} as { [k: string]: any }),
      processing: ref(false),
      recaptcha_key: ref(''),
      captchaResponse: ref(''),
      error_message: ref(''),
      success_message: ref(''),
    };
  },
  mounted() {
    this.setNewModel();
    this.setRecaptchaKey();
  },
  methods: {
    enterS() {
      this.submitForm();
    },

    setNewModel() {
      this.model['email'] = '';
      this.resetErrors();
    },

    resetErrors() {
      this.model['email_error_msg'] = '';
      this.model['email_error'] = false;
    },

    /**
     * AuthCard renders the success and error banners independently, so a stale
     * success message would sit under a fresh validation error. Every submit
     * starts here to keep exactly one of the two visible.
     */
    resetMessages() {
      this.success_message = '';
      this.resetErrors();
    },

    setRecaptchaKey() {
      if (!process.env.APP_VUE_RECAPTCHA_KEY) {
        logInfo('Recaptcha key is missing');
        return;
      }
      this.recaptcha_key = process.env.APP_VUE_RECAPTCHA_KEY;
    },

    captcaResp(captResponse: any) {
      this.captchaResponse = captResponse;
    },

    user_login() {
      this.$router.push('/');
    },

    async submitForm() {
      this.resetMessages();
      // Outside the try: an early return would still run `finally`, wiping the
      // validation error before the user sees it.
      if (!this.validateRow()) return;
      try {
        this.processing = true;
        const formData = new FormData();
        formData.append('email', this.model['email']);
        formData.append('captcha_response', this.captchaResponse);
        const response = await axios.post(api.forget_password, formData, {
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded',
            Authorization: getClientAuthorization(),
          },
        });

        if (!response.data?.success) throw response.data;

        // Fixed copy rather than response.data.message: the backend's wording
        // is not translated and varies by deployment.
        this.success_message = this.$t('forgot_password_link_sent');
        this.setNewModel();
      } catch (err: any) {
        this.handleSubmitError(err);
      } finally {
        this.processing = false;
        this.resetRecaptcha();
      }
    },

    /**
     * Captcha failures report inline on the email field; everything else toasts
     * the backend's own message.
     *
     * DOCB-9124's generic-banner normalisation was dropped deliberately, so any
     * user-enumeration signal the backend sends now reaches the user. Its
     * OpenAPI contract documents no user-not-found response (400/422 only), but
     * `MessageResponse.success` is a plain boolean — one stays expressible.
     */
    handleSubmitError(err: any) {
      logError(err);
      if (this.isCaptchaError(err)) {
        const msg = this.$t('recaptcha_invalid');
        this.model['email_error_msg'] = msg;
        this.model['email_error'] = true;
        notify.error(msg as string);
        return;
      }
      notify.error(String(ApiExceptions.getErrorMessage(err as dynamicObj)));
    },

    /**
     * A bare 400 means captcha by contract — the endpoint documents 400 as only
     * `Invalid ReCaptcha` (422 covers malformed input).
     */
    isCaptchaError(err: any): boolean {
      const status = err?.response?.status ?? err?.status;
      // submitForm() throws the bare `response.data` on a 200 + success:false,
      // so the code can sit at the top level too.
      const errorCode = err?.response?.data?.error_code ?? err?.error_code;
      return (
        status === 400 ||
        errorCode === 'recaptcha_invalid' ||
        errorCode === 'invalid_captcha' ||
        errorCode === 'captcha_invalid'
      );
    },

    validateRow() {
      let error = false;
      this.resetErrors();

      if (!this.model['email'] || this.model['email'].length == 0) {
        error = true;
        this.model['email_error_msg'] = this.$t('email_required');
        this.model['email_error'] = true;
      }
      let isEmailValid = this.validateEmail(this.model['email']);
      if (error === false && !isEmailValid) {
        error = true;
        this.model['email_error_msg'] = this.$t('email_invalid');
        this.model['email_error'] = true;
      }

      return !error;
    },

    resetRecaptcha() {
      try {
        (<any>this).$refs['recaptcha'].reset();
      } catch (err: any) {
        logError(err);
      }
    },
  },
});
</script>

<style scoped lang="scss">
.auth-submit-btn {
  width: 100%;
  height: 44px;
  font-weight: 500;
  border-radius: 0.5rem;
}
</style>
